import React from "react";

export function BoimatorDashboard() {
  return (
    <div dangerouslySetInnerHTML={{ __html: "<!DOCTYPE html>
<html lang="en" >
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />

  <title>Greeting Card</title>
  <style>
    @keyframes fadeInUp {
      0% {
        opacity: 0;
        transform: translateY(20px);
      }
      100% {
        opacity: 1;
        transform: translateY(0);
      }
    }
    .fade-in-up {
      animation: fadeInUp 0.8s ease forwards;
    }
  </style>
</head>
<body class="bg-gradient-to-r from-purple-400 via-pink-500 to-red-500 min-h-screen flex items-center justify-center p-4">

  <div class="max-w-md bg-white bg-opacity-90 rounded-3xl shadow-xl p-8 text-center fade-in-up">
    <h1 class="text-4xl font-extrabold text-purple-700 mb-4">Welcome Back!</h1>
    <p class="text-gray-700 text-lg mb-6">Hope you’re having a fantastic day. Let’s make it even better with some amazing projects ahead!</p>
    <button
      class="bg-purple-700 hover:bg-purple-800 text-white font-semibold py-3 px-8 rounded-full shadow-lg transition"

    >
      Say Hello
    </button>
  </div>

</body>
</html>" }} />
  );
}
